@import "@fontsource-variable/archivo/standard.css";

/* Light (sibling): pale grey paper #ececea, graphite ink #1d1d1d, the same square planes a
   step darker than the paper (#e2e2e0 rows, #d6d6d4 buttons), quiet links at 55% ink.
   No radius anywhere; the brand blue stays in the glow only. */
:root {
  --background: #ececea;
  --foreground: #1d1d1d;
  --card: #e2e2e0;
  --card-foreground: #1d1d1d;
  --popover: #f4f4f2;
  --popover-foreground: #1d1d1d;
  --primary: #d6d6d4;
  --primary-foreground: #1d1d1d;
  --secondary: #e2e2e0;
  --secondary-foreground: #1d1d1d;
  --muted: #d9d9d7;
  --muted-foreground: #7a7a78;
  --accent: #cacac8;
  --accent-foreground: #1d1d1d;
  --destructive: #b3261e;
  --destructive-foreground: #ffffff;
  --border: rgb(29 29 29 / 0.14);
  --input: rgb(29 29 29 / 0.2);
  --ring: #1d1d1d;
  --highlight: #2d62ff;
  --highlight-foreground: #ffffff;
  --glow: #2d62ff;
  --chart-1: #1d1d1d;
  --chart-2: #2d62ff;
  --chart-3: #7a7a78;
  --chart-4: #4a4a48;
  --chart-5: #b4b4b2;
  --sidebar: #e2e2e0;
  --sidebar-foreground: #1d1d1d;
  --sidebar-primary: #1d1d1d;
  --sidebar-primary-foreground: #ececea;
  --sidebar-accent: #d6d6d4;
  --sidebar-accent-foreground: #1d1d1d;
  --sidebar-border: rgb(29 29 29 / 0.14);
  --sidebar-ring: #1d1d1d;

  --typeface-body: "Archivo Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Archivo Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 0rem;
  --page-width: 90rem;
  --page-gutter: max(1.25rem, 2.43vw);
  --section-y: 6rem;

  /* theme-only: Archivo widened to Telegraf's set width (blocks fall back to 100%) */
  --k2space-stretch: 107%;
}

/* Dark (faithful): black #000 ground, soft grey ink #c5c5c5, #141414 cards, #1b1b1b rows and
   idle tabs, #252525 square buttons (hover #313131), #5e5e5e quiet text. The brand blue
   #2d62ff only tints placeholders as the glow. */
.dark {
  --background: #000000;
  --foreground: #c5c5c5;
  --card: #141414;
  --card-foreground: #c5c5c5;
  --popover: #141414;
  --popover-foreground: #c5c5c5;
  --primary: #252525;
  --primary-foreground: #c5c5c5;
  --secondary: #1b1b1b;
  --secondary-foreground: #c5c5c5;
  --muted: #161616;
  --muted-foreground: #5e5e5e;
  --accent: #313131;
  --accent-foreground: #c5c5c5;
  --destructive: #e5484d;
  --destructive-foreground: #000000;
  --border: rgb(197 197 197 / 0.14);
  --input: rgb(197 197 197 / 0.2);
  --ring: #c5c5c5;
  --highlight: #2d62ff;
  --highlight-foreground: #ffffff;
  --glow: #2d62ff;
  --chart-1: #c5c5c5;
  --chart-2: #2d62ff;
  --chart-3: #5e5e5e;
  --chart-4: #8a8a8a;
  --chart-5: #313131;
  --sidebar: #141414;
  --sidebar-foreground: #c5c5c5;
  --sidebar-primary: #c5c5c5;
  --sidebar-primary-foreground: #000000;
  --sidebar-accent: #252525;
  --sidebar-accent-foreground: #c5c5c5;
  --sidebar-border: rgb(197 197 197 / 0.14);
  --sidebar-ring: #c5c5c5;
}
